"% margin_03: cascaded (inner + outer) loop robust stability margins
% Inner:  G_in(s) = 1/(s(s+4)),  ki = 12,  unity negative feedback
% Outer:  G_out(s) = 2.5/(s(s+2))
% Total open loop L(s) = G_out(s) * G_in_cl(s); margins of L(s).

s = tf('s');

% --- INNER loop: close FIRST with unity negative feedback ---
ki     = 12.0;
G_in   = 1.0 / (s * (s + 4.0));
G_in_cl = feedback(ki * G_in, 1);        % feedback() defaults to negative feedback

% --- OUTER loop: cascade AFTER inner loop is closed ---
G_out  = 2.5 / (s * (s + 2.0));
L      = G_out * G_in_cl;                % total open loop

% --- margins: margin returns [Gm, Pm, Wcg, Wcp] in this exact order ---
[Gm, Pm, Wcg, Wcp] = margin(L);

% map outputs by position, no semantic remapping:
gm_db  = 20 * log10(Gm);   % linear gain margin -> dB
pm_deg = Pm;               % phase margin, already degrees
w_gc   = Wcg;              % 3rd output -> w_gc
w_pc   = Wcp;              % 4th output -> w_pc

% --- write result.json ---
r = struct('gm_db', gm_db, 'pm_deg', pm_deg, 'w_gc', w_gc, 'w_pc', w_pc);
fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(r));
fclose(fid);"
